import React, { useState, useEffect } from 'react';

export default function EvidenceHistory({ token }) {
  const [logs, setLogs] = useState([]);

  useEffect(() => {
    fetch('http://localhost:5000/api/evidence', {
      headers: { 'Authorization': `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => setLogs(data))
      .catch(err => console.error(err));
  }, [token]);

  return (
    <div>
      <h2>Recorded Evidence & Email Dispatch Log</h2>
      <div className="card" style={{ marginTop: '1.5rem', padding: '1rem' }}>
        <table className="evidence-table">
          <thead>
            <tr>
              <th>Timestamp</th>
              <th>Camera</th>
              <th>Location Type</th>
              <th>Violation Detected</th>
              <th>License Plate</th>
              <th>Email Status</th>
            </tr>
          </thead>
          <tbody>
            {logs.map(log => (
              <tr key={log.id}>
                <td>{new Date(log.timestamp).toLocaleString()}</td>
                <td>{log.cameraName}</td>
                <td><span className="location-badge">{log.locationType}</span></td>
                <td style={{ color: '#f87171', fontWeight: 'bold' }}>{log.alertType}</td>
                <td>{log.plateNumber}</td>
                <td>
                  <span className={`status-tag ${log.status.toLowerCase().includes('sent') ? 'sent' : 'failed'}`}>
                    {log.status}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
